(()=>{"use strict";const BATCH=20,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],panels=$$(".section-panel"),tabs=$$(".tab-btn"),search=$("#search"),yearFilter=$("#yearFilter"),topicFilter=$("#topicFilter"),shiftFilter=$("#shiftFilter"),emptyState=$("#emptyState"),themeToggle=$("#themeToggle");let db={sections:{}},currentSection="numerical",filtered=[],rendered=0,observer=null;function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[m]))}function selectedYear(){return yearFilter?.value||""}function data(){const a=db.sections[currentSection]||[],y=selectedYear();return y?a.filter(q=>String(q.year||"")===y):a}function allYears(){const s=new Set;Object.values(db.sections).forEach(a=>a.forEach(q=>q.year&&s.add(String(q.year))));return [...s].sort((a,b)=>Number(b)-Number(a))}function panel(){return $("#panel-"+currentSection)}function topics(){const m=new Map;data().forEach(q=>{if(!m.has(q.topic))m.set(q.topic,{label:q.label,count:0});m.get(q.topic).count++});return m}function populateYears(){if(!yearFilter)return;const y=allYears();yearFilter.innerHTML='<option value="">All years</option>'+y.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join("")}function populateTopics(){const p=panel(),g=p.querySelector(".topic-grid"),m=topics();g.innerHTML=[...m].map(([t,x])=>`<button type="button" class="topic-button count-card" data-topic-button="${esc(t)}"><span class="count-num">${x.count}</span><span class="count-label">${esc(x.label)}</span></button>`).join("");topicFilter.innerHTML='<option value="">All topics in current section</option>'+[...m].map(([t,x])=>`<option value="${esc(t)}">${esc(x.label)}</option>`).join("");g.querySelectorAll(".topic-button").forEach(b=>b.addEventListener("click",()=>{const t=b.dataset.topicButton,on=b.classList.contains("active");g.querySelectorAll(".topic-button").forEach(x=>x.classList.remove("active"));topicFilter.value=on?"":t;if(!on)b.classList.add("active");apply();window.scrollTo({top:0,behavior:"smooth"})}))}function card(q){const isOld=Number(q.year)===2024;const meta=isOld?`<span class="pill category">${esc(q.label)}</span><span class="qno">${esc(q.qno)}</span>`:`<span class="pill shift">Shift ${esc(q.shift)}</span><span class="pill date">${esc(q.date)}</span><span class="pill category">${esc(q.label)}</span><span class="qno">${esc(q.qno)}</span>`;return `<article class="question-card" data-category="${esc(q.topic)}" data-shift="${esc(q.shift||"")}" data-year="${esc(q.year||"")}"><div class="meta">${meta}</div><div class="question">${esc(q.q)}</div><div class="options" role="group" aria-label="Answer options">${q.o.map((o,i)=>{const l="ABCD"[i];return `<button type="button" class="option-btn" data-option="${l}"><span class="option-letter">${l}</span><span class="option-text">${esc(o)}</span></button>`}).join("")}</div><div class="answer" data-answer="${esc(q.a)}"><strong>Correct Answer:</strong> ${esc(q.a)}</div></article>`}function bind(root){root.querySelectorAll(".question-card").forEach(c=>{const a=c.querySelector(".answer")?.dataset.answer,o=[...c.querySelectorAll(".option-btn")];o.forEach(b=>b.addEventListener("click",()=>{if(b.classList.contains("locked"))return;o.forEach(x=>{x.classList.add("locked");x.setAttribute("aria-disabled","true")});if(b.dataset.option===a)b.classList.add("correct");else{b.classList.add("wrong");c.querySelector(`.option-btn[data-option="${a}"]`)?.classList.add("correct")}}))})}function batch(){const g=panel().querySelector(".questions-grid"),end=Math.min(rendered+BATCH,filtered.length);if(!rendered)g.innerHTML="";g.appendChild(document.createRange().createContextualFragment(filtered.slice(rendered,end).map(card).join("")));bind(g);rendered=end;emptyState.style.display=filtered.length?"none":"block";if(rendered>=filtered.length)observer?.disconnect()}function observe(){observer?.disconnect();const p=panel(),old=p.querySelector(".load-sentinel");old?.remove();const s=document.createElement("div");s.className="load-sentinel";p.querySelector(".questions-grid").after(s);observer=new IntersectionObserver(e=>e[0].isIntersecting&&batch(),{rootMargin:"800px"});observer.observe(s)}function apply(){const q=search.value.trim().toLowerCase(),t=topicFilter.value.toLowerCase(),sh=shiftFilter.value;filtered=data().filter(x=>(!q||`${x.q} ${x.o.join(" ")} ${x.label} ${x.year||""}`.toLowerCase().includes(q))&&(!t||x.topic===t)&&(!sh||String(x.shift||"")===sh));rendered=0;panel().querySelector(".questions-grid").innerHTML="";panel().querySelectorAll(".topic-button").forEach(b=>b.classList.toggle("active",!!t&&b.dataset.topicButton===t));batch();observe()}function switchSection(s){currentSection=s;panels.forEach(p=>p.classList.toggle("active",p.dataset.section===s));tabs.forEach(t=>t.classList.toggle("active",t.dataset.target===s));search.value="";shiftFilter.value="";topicFilter.value="";populateTopics();apply()}tabs.forEach(t=>t.addEventListener("click",()=>switchSection(t.dataset.target)));const savedTheme=localStorage.getItem("rrbje-theme");if(savedTheme==="dark"||savedTheme==="light")document.documentElement.dataset.theme=savedTheme;function updateThemeButton(){const dark=document.documentElement.dataset.theme==="dark";themeToggle.innerHTML=dark?'<span class="theme-icon">☀</span><span class="theme-label">Light Mode</span>':'<span class="theme-icon">☾</span><span class="theme-label">Dark Mode</span>';themeToggle.setAttribute("aria-label",dark?"Switch to light mode":"Switch to dark mode")}function toggleTheme(){const dark=document.documentElement.dataset.theme==="dark";document.documentElement.dataset.theme=dark?"light":"dark";localStorage.setItem("rrbje-theme",dark?"light":"dark");updateThemeButton()}themeToggle?.addEventListener("click",toggleTheme);updateThemeButton();yearFilter?.addEventListener("change",()=>{topicFilter.value="";populateTopics();apply()});search.addEventListener("input",apply);shiftFilter.addEventListener("change",apply);topicFilter.addEventListener("change",apply);async function init(){try{const r=await fetch("/data/questions.v4.min.json",{cache:"force-cache"});if(!r.ok)throw Error(r.status);db=await r.json();populateYears();switchSection("numerical")}catch(e){console.error(e);emptyState.textContent="Unable to load questions. Please refresh the page.";emptyState.style.display="block"}}init()})();
